INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare Knock', 'Nightmare knock is a visual novel about a simple man who gets knocked on his window at night. What happens next is up to you, because there are many choices in the game that affect the story and whether you survive the night. 8 possible endings, only one of which you will survive. Nice atmospheric graphics, your own soundtrack, and high-quality sounds will plunge the user into an atmosphere of despair and fear.' FROM games WHERE igdb_id = 237518 ON CONFLICT (game_id, language_code) DO NOTHING;
