INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mistrick', 'You play as John Blanc, a narcissistic convict, who finds himself trapped in a strange pocket dimension. Soon after his arrival, he is greeted by a former cell neighbor and executed serial killer, Chase Colt. While Chase claims that John has already died, this quickly turns out to be a malicious lie to keep John trapped in this world. Will he be able to figure out a way to escape, or will he die to the many tricks of this wicked place?' FROM games WHERE igdb_id = 194514 ON CONFLICT (game_id, language_code) DO NOTHING;
