INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sneaky IT Support', 'Sneaky IT Support is a simulation game where you find naughty secrets in employee computers. Every laptop has a problem you have to fix within a given time limit. If you''re fast enough, you''ll have time to look around for their naughty secrets. The more secrets you find, the more money you''ll make.' FROM games WHERE igdb_id = 211572 ON CONFLICT (game_id, language_code) DO NOTHING;
