INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Macs World', 'Mac''s World is a single-player 3D adventure game in which a young pup explores the many floors of a mysterious mansion on a quest to collect as many chicken legs as he can. Traverse 10 unique levels while dodging bombs, solving puzzles, and smacking enemies away with a trusty frying pan. But be careful, as unknown dangers lurk around each corner of the mansion. Is there a haunting afoot? Mac, along with his trusty animal sidekick, will have to face their fears to find out.' FROM games WHERE igdb_id = 193714 ON CONFLICT (game_id, language_code) DO NOTHING;
