INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sarrisa and the Legendary Sword', 'Sarissa and the Legendary Sword is a Brazilian turn-based RPG, with a simple and beautiful story. In it, you will follow friends, Sarissa, Dandara, Elaine and Patricia, as they go on an adventurous journey, where love and friendship, and a fated destiny will change their lives forever.' FROM games WHERE igdb_id = 197297 ON CONFLICT (game_id, language_code) DO NOTHING;
