INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Sing 2023 with German Hits', 'Turn your living room into a stage with Let''s Sing! Sing alone or challenge your friends to a singing duel in local or online multiplayer. Have fun in Let''s Party mode, where you can perform together with up to eight players, or sing your way to the top of the global online leaderboard. Perform some of your new favorite songs as well as old classics from the new song selection with 30 exciting and well-known tracks. Rock the stage with the latest hits like Ed Sheeran''s ''Bad Habits'', Lil Nas X ft. ''Old Town Road'' by Billy Ray Cyrus, Billie Eilish''s ''Happier Than Ever'', BTS'' ''Butter'', ''Bye Bye " by Sarah Connor or "Three o''clock at night" by Mark Forster & LEA.' FROM games WHERE igdb_id = 227612 ON CONFLICT (game_id, language_code) DO NOTHING;
