INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Sing 2023: Incluye Canciones Españolas', 'Turn your living room into a stage with Let''s Sing! Sing solo or with friends, either as a duet or challenge each other in online and offline game modes. Have fun with Let''s Party mode, where you can sync up with up to eight singers or climb to the top of the online global leaderboard. Play some of your new favorite songs as well as the best-known classics from the new song selection that includes 35 exciting and popular tracks.' FROM games WHERE igdb_id = 221328 ON CONFLICT (game_id, language_code) DO NOTHING;
