INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Perfect Hotel', 'Ever dreamed of running your own hotel? Start from the ground up in this fun and fast-paced time-management game where the aim is to build an accommodation empire and demonstrate your dedication to hospitality. Show your skills as a hotel manager, invest wisely in staff and property improvements, and work your socks off to become a hospitality tycoon in this addictive and entertaining casual simulator.' FROM games WHERE igdb_id = 216047 ON CONFLICT (game_id, language_code) DO NOTHING;
