INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CubeCrafter', 'Looking for a casual crafting game that combines resource collecting and time management with action and adventure? CubeCraft is an enjoyable and original game that covers all the angles – a world-building simulator where you gather resources, craft all sorts of different structures, get to explore a wide and varied game world, and even do a little fighting now and then. And bear in mind, you can do all that while riding around on the back of a pig! (Not to mention all the sheep, who provide useful wool and get in the way a lot…)' FROM games WHERE igdb_id = 248596 ON CONFLICT (game_id, language_code) DO NOTHING;
