INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey: The Heart of Gaia', 'One evening a stranger appears at Liz''s doorway, whisking her away to a colorful world that lies deep within the center of the Earth. Not only is it controlled by a powerful tyrant, but the very heart of Underworld is dying! Can Liz save this world and find the way back to her own? Journey through a fantastic landscape filled with quirky characters. Rescue the captured citizens, and they will help you put an end to the tyranny of Scartaris Umbra! Dive deep into the world of Journey: The Heart of Gaia, a thrilling puzzle adventure!' FROM games WHERE igdb_id = 50463 ON CONFLICT (game_id, language_code) DO NOTHING;
