INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ratcheteer', 'Play as an apprentice mechanic tasked with maintaining steam-powered cryo-colonies constructed for humanity to sleep out an impact winter following a celestial collision. Your master mechanic is abducted during some unplanned maintenance, setting off a lo-fi, top-down, action-adventure that finds the young Ratcheteer exploring the interconnected tunnels below the surface and a vast snowcean above to rescue friends, foes, and strangers alike.' FROM games WHERE igdb_id = 151977 ON CONFLICT (game_id, language_code) DO NOTHING;
