INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Deer Hunting: Out West', 'New simulation, more great deer hunting, increased challenges! Pro Deer Hunting Out West has both whitetail deer and mule deer hunting in any one of six hunting areas dispersed througout three different states. Use your climbing stand to succesfully call and still hunt for whitetail bucks. For the out west levels, use you drone to locate then stalk and hunt mule deer bucks with the aid of your map. Pro and action mode have returned with improved ballistics and artificial intelligence. Continue the tradition and become the new Pro Deer Hunter!' FROM games WHERE igdb_id = 194361 ON CONFLICT (game_id, language_code) DO NOTHING;
