INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Vadimka II: Revenge of Dr. Kulik', 'Super Vadimka II: Revenge of Dr. Kulik is a free horror platformer developed by VadimBallzGames for Windows. This sequel to Super Vadimka marks the continuation of the thrilling Super Vadimka series, bringing back the ingenious designer who crafted numerous levels filled with formidable bosses and devious traps. In this installment, players face the sinister Dr. Kulik, who aims to conquer the world once more. Prepare for a harrowing adventure as you traverse dangerous landscapes, battling monstrous foes and navigating treacherous hazards.' FROM games WHERE igdb_id = 194612 ON CONFLICT (game_id, language_code) DO NOTHING;
