INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle by Nikoli W: Sudoku', 'Sudoku is a puzzle in which you place numbers from 1 to 9 into a 9x9 grid, divided into horizontal and vertical lines and 3x3 blocks, filling up all of the spaces with the numbers. With everything from simple puzzles to super-difficult ones, this game is popular with a wide range of players, from beginners to veterans. Please enjoy this high-quality sudoku game.' FROM games WHERE igdb_id = 218511 ON CONFLICT (game_id, language_code) DO NOTHING;
