INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution A3', 'Dance Dance Revolution A3 (pronounced Ace Three) is the 18th installment of the Dance Dance Revolution arcade series in Japan, and the sequel to Dance Dance Revolution A20 Plus. The game was released as an update on golden cabinets in Japan on March 17, 2022, including those imported in the United States. An upgrade for older cabinets was released in Asia (including Japan, South Korea, and several other countries), Australasia, and the United States on June 22, 2022, with a larger U.S. rollout on August 19th, 2023.' FROM games WHERE igdb_id = 253128 ON CONFLICT (game_id, language_code) DO NOTHING;
