INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Coloring Book 2', 'Did you know that coloring relaxes your brain, reduces stress, improves focus, motor skill and vision? My Coloring Book 2 will bring all those benefits to your Nintendo Switch! There are two types of drawings to choose from: 61 about land and 49 marine animals. Thanks to an amazing variety, My Coloring Book is suitable for all from children to adults. Save your work for later and show off your artistic sense and skill to family and friends.' FROM games WHERE igdb_id = 196184 ON CONFLICT (game_id, language_code) DO NOTHING;
