INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('red-white-yellow-zinger', 196182, '2022-04-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5aqm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1jyr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red White Yellow Zinger', '- A puzzle game in which blocks are erased in the order of red, white, and yellow! - Collaboration with popular music creator Room97! This is a falling puzzle in which six blocks of three different colors are lined up and erased. The blocks can only be erased in order. Blocks of indelible colors can be aligned first to form a chain. BGM is played while the block disappears and until the next block disappears. In the meantime, you can keep the BGM playing by aligning the next block and continuing to erase it. Advanced users can even play a full song. All songs are in collaboration with popular music creator Room97! The wide range of sounds, from K-POP to nostalgic melodies, employing a variety of singers, enhances the pleasantness of the combo.' FROM games WHERE igdb_id = 196182 ON CONFLICT (game_id, language_code) DO NOTHING;
