INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fate Seeker: Mission', 'Fate Seeker: Mission has launched its first Martial Art mobile game, offering millions of players an opportunity to create their own skill combinations and unify the world with authentic Martial Art. The game is a Roguelite Combat that offers stress-free mode with player''s own choices at the tip of their fingers. Upgrade your champions idling and enjoy casual, fun, and exciting battles over a series of adventures' FROM games WHERE igdb_id = 304162 ON CONFLICT (game_id, language_code) DO NOTHING;
