INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grederys', 'Grederys - is a short indie horror game with elements of stealth. The plot of the game revolves around the protagonist Kleit Kremer, who, returning home by taxi, gets into a terrible car accident. Test your strength in finding all the necessary items, keys and try to escape from the monsters.' FROM games WHERE igdb_id = 201226 ON CONFLICT (game_id, language_code) DO NOTHING;
