INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Annie and the Art Gallery', 'After months of waiting, Annie finally snags a ticket to the new art exhibit. However, things take a turn for the worst: she finds herself trapped in the museum''s haunted basement. Help her navigate puzzles, traps, and more as she tries to escape - and find out the truth of what''s really going on.' FROM games WHERE igdb_id = 192656 ON CONFLICT (game_id, language_code) DO NOTHING;
