INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('merge-survival-wasteland', 250175, '2022-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bie.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2jvu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Merge Survival: Wasteland', 'Hello. My name is Eden and ever since "that day", I have become alone and been living a wandering life. Due to many people''s selfishness, our environment has been destroyed and became a difficult world to live in. Living alone in this world full of chaos is very exhausting and lonely. Can I possibly survive in a place like this...? Hey, you there! I think you can help me out! Could you please help me out so I can stay safe and survive in this world of misery? This is a story of people surviving in the post-apocalypse world created by environmental pollution and disasters. Merge to create survival materials, and find any new resources or hidden locations by exploring.' FROM games WHERE igdb_id = 250175 ON CONFLICT (game_id, language_code) DO NOTHING;
