INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Faircroft''s Antiques: The Forbidden Crypt - Collector''s Edition', 'When an old friend requests Mia’s help restoring an old cathedral, she packs her bags for the seaside town of Porto Nacosti, Italy! But she soon finds trouble in paradise - a crypt below the church holds a long-lost secret that a powerful family is desperate to keep. Search through visually dazzling hidden-object scenes, restore art pieces in need of love, and reveal what history forgot in Faircroft''s Antiques: The Forbidden Crypt!' FROM games WHERE igdb_id = 186948 ON CONFLICT (game_id, language_code) DO NOTHING;
