INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ilum', 'Action open-world game that includes elements of exploration. Taking place in ancient Babylon and the surrounding region, including cities like Borsippa, Sippar, Kutha and Kish, among others. The year is 539 BC, the time when the Babylonian empire feel to the Persians and its Jewish captives released from servitude after 70 years. As prophesied, Babylon is to be destroyed. Ilum accurately depicts archaeological findings and cuneiform inscriptions from buildings such as the Tower of Babel, Hanging Gardens and Nebuchadnezzar''s palaces. Voice-acted in Akkadian language in a Biblical and Babylonian mythological background.' FROM games WHERE igdb_id = 178168 ON CONFLICT (game_id, language_code) DO NOTHING;
