INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hike', 'The Hike is a first person horror/puzzle game in which you must push through the horrors that start in the much feared forests of the Mount Grandious National Park. Use your skills to make it back to society... and use your legs, you''re no fighter.' FROM games WHERE igdb_id = 188920 ON CONFLICT (game_id, language_code) DO NOTHING;
