INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Patrick''s Day Break 2 Head to Head', 'Saint Patricks Day Break 2 Head to Head is a retro arcade game that lets 1 and 2 players play head to head in a competitive arcade environment. Unique animated Saint Patrick’s day themed items tumble down toward the users paddle along with Mini-Bosses and Powerups. Collect powerups as you progress through the levels and defeat your opponent. Thirty Levels to compete in and battle mini bosses on your way to victory in single player and two player modes.' FROM games WHERE igdb_id = 194360 ON CONFLICT (game_id, language_code) DO NOTHING;
