INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunvolt Chronicles: Luminous Avenger iX 2 - Limited Edition', 'Gunvolt Chronicles: Luminous Avenger iX 2 is the direct sequel to Gunvolt Chronicles: Luminous Avenger iX! This new game takes the original speedy and stylish 2D action gameplay to the next level as Copen rips through enemies with his new "Break-Shift" form. His new destructive capabilities makes the high-speed action more satisfying than ever! Experience a new apex of cutting-edge 2D action with Luminous Avenger iX 2!INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 186922 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
